import{_ as a,o as e,c as s,al as n}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Безперервна інтеграція","description":"","frontmatter":{},"headers":[],"relativePath":"uk/test_and_ci/continous_integration.md","filePath":"uk/test_and_ci/continous_integration.md"}'),d={name:"uk/test_and_ci/continous_integration.md"};function o(r,t,i,l,c,p){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="безперервна-інтеграція" tabindex="-1">Безперервна інтеграція <a class="header-anchor" href="#безперервна-інтеграція" aria-label="Permalink to &quot;Безперервна інтеграція&quot;">​</a></h1><p>PX4 uses GitHub Actions for continuous integration, with different workflows handling code builds, testing, and documentation.</p><h2 id="documentation-ci" tabindex="-1">Documentation CI <a class="header-anchor" href="#documentation-ci" aria-label="Permalink to &quot;Documentation CI&quot;">​</a></h2><p>The documentation pipeline handles building, deploying, and translating the PX4 User Guide. All documentation CI is consolidated into a single orchestrator workflow organized in tiers.</p><h3 id="docs-orchestrator" tabindex="-1">Docs Orchestrator <a class="header-anchor" href="#docs-orchestrator" aria-label="Permalink to &quot;Docs Orchestrator&quot;">​</a></h3><p><strong>Workflow file:</strong> <a href="https://github.com/PX4/PX4-Autopilot/blob/main/.github/workflows/docs-orchestrator.yml" target="_blank" rel="noreferrer"><code>docs-orchestrator.yml</code></a></p><p>This is the main documentation workflow. It runs on pull requests, pushes to <code>main</code> and <code>release/**</code> branches, and manual <code>workflow_dispatch</code> triggers, performing different jobs depending on the trigger event. Jobs are organized in tiers, where each tier depends on the previous one completing successfully.</p><h4 id="tier-structure" tabindex="-1">Tier Structure <a class="header-anchor" href="#tier-structure" aria-label="Permalink to &quot;Tier Structure&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Tier</th><th>Job</th><th>PR</th><th>Push / Dispatch</th><th>Опис</th></tr></thead><tbody><tr><td>T1</td><td>Detect Changes</td><td>Так</td><td>—</td><td>Checks if source code files changed (triggers metadata regen)</td></tr><tr><td>T2</td><td>PR Metadata</td><td>Yes (conditional)</td><td>—</td><td>Builds PX4 SITL and regenerates all auto-generated docs</td></tr><tr><td>T2</td><td>Metadata Sync</td><td>—</td><td>Так</td><td>Builds PX4 SITL, regenerates metadata, auto-commits</td></tr><tr><td>T2</td><td>Link Check</td><td>Так</td><td>—</td><td>Checks for broken links in changed files, posts PR comment</td></tr><tr><td>T3</td><td>Build Site</td><td>Yes (if docs/source changed)</td><td>Yes (after T2)</td><td>Builds the VitePress documentation site</td></tr><tr><td>T4</td><td>Deploy</td><td>—</td><td>Так</td><td>Deploys to AWS S3</td></tr></tbody></table><h4 id="pull-request-flow" tabindex="-1">Pull Request Flow <a class="header-anchor" href="#pull-request-flow" aria-label="Permalink to &quot;Pull Request Flow&quot;">​</a></h4><p>When a PR modifies files in <code>docs/**</code> or the orchestrator workflow file itself, the workflow validates the changes:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PR Event</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ T1: Detect Changes                  │</span></span>
<span class="line"><span>│  • Checks if src/msg/ROMFS changed  │</span></span>
<span class="line"><span>└─────────────────┬───────────────────┘</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>          ┌───────┴───────┐</span></span>
<span class="line"><span>          ▼               ▼</span></span>
<span class="line"><span>┌──────────────────┐ ┌─────────────────────────┐</span></span>
<span class="line"><span>│ T2: PR Metadata  │ │ T2: Link Check (~30s)   │</span></span>
<span class="line"><span>│ (conditional)    │ │  • Detects changed .md   │</span></span>
<span class="line"><span>│  • Builds SITL   │ │  • Runs filtered check   │</span></span>
<span class="line"><span>│  • Generates     │ │  • Posts PR comment      │</span></span>
<span class="line"><span>│    metadata      │ │  • Runs full check       │</span></span>
<span class="line"><span>│  • Builds        │ └────────────┬────────────┘</span></span>
<span class="line"><span>│    failsafe web  │              │</span></span>
<span class="line"><span>└────────┬─────────┘              │</span></span>
<span class="line"><span>         └───────────┬────────────┘</span></span>
<span class="line"><span>                     ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ T3: Build Site (~7-10 min)         │</span></span>
<span class="line"><span>│  (skipped if only workflow YAML     │</span></span>
<span class="line"><span>│   changed — no docs/source changes) │</span></span>
<span class="line"><span>│  • Builds VitePress site            │</span></span>
<span class="line"><span>│  • Verifies no build errors         │</span></span>
<span class="line"><span>└─────────────────┬───────────────────┘</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>                DONE</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Job</th><th>Duration</th><th>Опис</th></tr></thead><tbody><tr><td><strong>T1: Detect Changes</strong></td><td>~10s</td><td>Determines if metadata regeneration is needed</td></tr><tr><td><strong>T2: PR Metadata</strong></td><td>~10-15m</td><td>Rebuilds PX4 SITL and regenerates all metadata (only if source files changed)</td></tr><tr><td><strong>T2: Link Check</strong></td><td>~30s</td><td>Checks for broken links in changed markdown files and posts a sticky comment to the PR (skipped on fork PRs)</td></tr><tr><td><strong>T3: Build Site</strong></td><td>~7-10m</td><td>Builds the VitePress site to verify there are no build errors. Skipped when only the workflow YAML changed (no docs or source changes).</td></tr></tbody></table><h4 id="push-dispatch-flow-main-release-branches" tabindex="-1">Push / Dispatch Flow (main/release branches) <a class="header-anchor" href="#push-dispatch-flow-main-release-branches" aria-label="Permalink to &quot;Push / Dispatch Flow (main/release branches)&quot;">​</a></h4><p>When changes are pushed to <code>main</code> or <code>release/**</code> branches (or a <code>workflow_dispatch</code> is triggered), the workflow regenerates metadata, builds, and deploys. Only <code>main</code> and <code>release/*</code> branches are accepted for deploy — other branches will fail with a clear error.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Push / Dispatch Event</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ T2: Metadata Sync (~10-15 min)     │</span></span>
<span class="line"><span>│  • Builds px4_sitl_default          │</span></span>
<span class="line"><span>│  • Generates parameter/airframe/    │</span></span>
<span class="line"><span>│    module documentation             │</span></span>
<span class="line"><span>│  • Builds failsafe web simulator    │</span></span>
<span class="line"><span>│  • Formats with Prettier            │</span></span>
<span class="line"><span>│  • Auto-commits if changes detected │</span></span>
<span class="line"><span>│    (with [skip ci])                 │</span></span>
<span class="line"><span>└─────────────────┬───────────────────┘</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ T3: Build Site (~7-10 min)         │</span></span>
<span class="line"><span>│  • Builds VitePress site            │</span></span>
<span class="line"><span>│  • Uploads build artifact           │</span></span>
<span class="line"><span>└─────────────────┬───────────────────┘</span></span>
<span class="line"><span>                  │</span></span>
<span class="line"><span>                  ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ T4: Deploy (~3 min)                │</span></span>
<span class="line"><span>│  • Syncs to AWS S3                  │</span></span>
<span class="line"><span>│  • HTML: 60s cache                  │</span></span>
<span class="line"><span>│  • Assets: 24h immutable cache      │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Job</th><th>Duration</th><th>Опис</th></tr></thead><tbody><tr><td><strong>T2: Metadata Sync</strong></td><td>~10-15m</td><td>Rebuilds PX4 SITL, regenerates all metadata, formats with Prettier, auto-commits with <code>[skip ci]</code></td></tr><tr><td><strong>T3: Build Site</strong></td><td>~7-10m</td><td>Builds the VitePress documentation site</td></tr><tr><td><strong>T4: Deploy</strong></td><td>~3m</td><td>Syncs built site to AWS S3 (HTML: 60s cache, assets: 24h cache)</td></tr></tbody></table><p>Crowdin upload is handled by a separate workflow (see below).</p><h4 id="generated-metadata" tabindex="-1">Generated Metadata <a class="header-anchor" href="#generated-metadata" aria-label="Permalink to &quot;Generated Metadata&quot;">​</a></h4><p>The metadata regeneration job creates the following auto-generated documentation:</p><table tabindex="0"><thead><tr><th>Тип</th><th>Output</th><th>Опис</th></tr></thead><tbody><tr><td>Параметри</td><td><code>docs/en/advanced_config/parameter_reference.md</code></td><td>Complete parameter reference</td></tr><tr><td>Планери</td><td><code>docs/en/airframes/airframe_reference.md</code></td><td>Airframe configurations</td></tr><tr><td>Модулі</td><td><code>docs/en/modules/*.md</code></td><td>Module documentation</td></tr><tr><td>Messages</td><td><code>docs/en/msg_docs/*.md</code></td><td>uORB message documentation</td></tr><tr><td>uORB Graphs</td><td><code>docs/public/middleware/*.json</code></td><td>Topic dependency graphs</td></tr><tr><td>Failsafe Simulator</td><td><code>docs/public/config/failsafe/*</code></td><td>Interactive failsafe simulator (WebAssembly)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not manually edit the auto-generated files listed above. They are overwritten on every push to main.</p></div><h4 id="path-triggers" tabindex="-1">Path Triggers <a class="header-anchor" href="#path-triggers" aria-label="Permalink to &quot;Path Triggers&quot;">​</a></h4><p>The workflow triggers on different paths depending on the event:</p><p><strong>Push</strong> (main/release branches):</p><table tabindex="0"><thead><tr><th>Path</th><th>Reason</th></tr></thead><tbody><tr><td><code>docs/**</code></td><td>Documentation source files</td></tr><tr><td><code>src/**</code></td><td>Source code changes affect metadata</td></tr><tr><td><code>msg/**</code></td><td>Message definitions affect metadata</td></tr><tr><td><code>ROMFS/**</code></td><td>ROMFS files affect metadata</td></tr><tr><td><code>Tools/module_config/**</code></td><td>Module configuration affects metadata</td></tr></tbody></table><p><strong>Pull Request:</strong></p><table tabindex="0"><thead><tr><th>Path</th><th>Reason</th></tr></thead><tbody><tr><td><code>docs/**</code></td><td>Documentation source files</td></tr><tr><td><code>.github/workflows/docs-orchestrator.yml</code></td><td>Changes to the workflow itself</td></tr></tbody></table><p>Source-only changes on PRs are detected at runtime by the T1: Detect Changes job using <a href="https://github.com/dorny/paths-filter" target="_blank" rel="noreferrer">dorny/paths-filter</a>, which conditionally triggers the T2: PR Metadata job.</p><h3 id="crowdin-download-workflow" tabindex="-1">Crowdin Download Workflow <a class="header-anchor" href="#crowdin-download-workflow" aria-label="Permalink to &quot;Crowdin Download Workflow&quot;">​</a></h3><p><strong>Workflow file:</strong> <a href="https://github.com/PX4/PX4-Autopilot/blob/main/.github/workflows/docs_crowdin_download.yml" target="_blank" rel="noreferrer"><code>docs_crowdin_download.yml</code></a></p><p>This scheduled workflow downloads completed translations from Crowdin and creates pull requests.</p><table tabindex="0"><thead><tr><th>Налаштування</th><th>Значення</th></tr></thead><tbody><tr><td><strong>Schedule</strong></td><td>Every Sunday at 00:00 UTC</td></tr><tr><td><strong>Target Languages</strong></td><td>Korean (ko), Ukrainian (uk), Chinese Simplified (zh-CN)</td></tr></tbody></table><p><strong>Process:</strong></p><ol><li>Downloads translations for each target language from Crowdin</li><li>Creates a separate PR for each language with new translations</li><li>PRs are labeled &quot;Documentation&quot; and assigned for review</li></ol><h3 id="caching-strategy" tabindex="-1">Caching Strategy <a class="header-anchor" href="#caching-strategy" aria-label="Permalink to &quot;Caching Strategy&quot;">​</a></h3><p>The workflows use caching to speed up builds:</p><table tabindex="0"><thead><tr><th>Cache</th><th>Розмір</th><th>Ціль</th></tr></thead><tbody><tr><td>ccache</td><td>1GB</td><td>C++ compilation cache for SITL builds</td></tr><tr><td>node_modules</td><td>~26MB</td><td>Node.js dependencies for VitePress</td></tr></tbody></table><h3 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h3><p>Jobs run on <a href="https://runs-on.com/" target="_blank" rel="noreferrer">runs-on</a> self-hosted runners with S3 cache:</p><table tabindex="0"><thead><tr><th>Job</th><th>Runner</th></tr></thead><tbody><tr><td>T1: Detect Changes</td><td>ubuntu-latest</td></tr><tr><td>T2: PR Metadata</td><td>4 CPU (with px4-dev container)</td></tr><tr><td>T2: Metadata Sync</td><td>4 CPU (with px4-dev container)</td></tr><tr><td>T2: Link Check</td><td>ubuntu-latest</td></tr><tr><td>T3: Build Site</td><td>4 CPU</td></tr><tr><td>T4: Deploy</td><td>ubuntu-latest</td></tr></tbody></table>`,41)])])}const g=a(d,[["render",o]]);export{u as __pageData,g as default};
